## Experiments to Port

### 1. step_scan_x / step_scan_y / step_scan_z
```rhai
// scripts/libs/step_scan.rhai
fn step_scan_y(grating, grating_pos, start, end, step_size, pulses_per_shot) {
    let spec = create_andor_spectrograph();
    let cam = get_gated_camera("andor_istar");
    let stage = create_dover_stage();

    spec.set_grating(grating);
    spec.set_wavelength(grating_pos);

    let positions = range(start, end + step_size, step_size);
    let spectra = [];

    for y in positions {
        stage.move_abs(y);
        sleep(0.5);
        let spectrum = with_shutter(spec, || {
            get_spectrum(cam, spec, pulses_per_shot, true)
        });
        spectra.push(#{y_position: y, spectrum: spectrum});
    }

    spectra
}
```

