fn height_scan(grating, grating_pos, z_start, z_end, z_step,
               x_start, x_step, y_position, pulses_per_shot) {
    let spec = create_andor_spectrograph();
    stage.y_move_abs(y_position);
    stage.x_move_abs(x_start);

    let results = [];
    let z_positions = range(z_start, z_end + z_step, z_step);

    for (i, z) in z_positions.enumerate() {
