## Rhai Port
```rhai
// scripts/libs/delay_scan.rhai
fn delay_scan(grating, grating_pos, delay_start, delay_stop, delay_step,
              start_y, step_size, pulses_per_shot) {
    let spec = create_andor_spectrograph();
    let cam = get_gated_camera("andor_istar");
    let stage = create_dover_stage();

    spec.set_grating(grating);
    spec.set_wavelength(grating_pos);

    let original_delay = cam.get_ddg_delay();
    let original_width = cam.get_ddg_width();

    let delays = range(delay_start, delay_stop + delay_step, delay_step);
    let results = [];
    let y = start_y;

    for delay in delays {
        stage.y_move_abs(y);
        y += step_size;  // Move to fresh spot

        // Set DDG timing
        cam.set_ddg_timing(delay, (delay_step * 0.8) as i64);
        sleep(0.5);

        let spectrum = with_shutter(spec, || {
            get_spectrum(cam, spec, pulses_per_shot, true)
        });

        results.push(#{
            delay_ps: delay,
            y_position: y - step_size,
            spectrum: spectrum
        });
    }

    // Restore original settings
    cam.set_ddg_timing(original_delay, original_width);

    results
}
```

