## Experiments to Port

### 1. step_scan_2d (experiments.py:692-756)
Standard grid scan using step-and-acquire:
```rhai
fn step_scan_2d(grating, grating_pos, 
                x_start, x_stop, x_step,
                y_start, y_stop, y_step,
                pulses_per_shot, sample_name, filepath) {
    let results = [];

    for y in range(y_start, y_stop + y_step, y_step) {
        stage.y_move_abs(y);
        sleep(5.0);  // Settle time

        let row = step_scan_x(grating, grating_pos, x_start, x_stop, x_step, pulses_per_shot);
        results.push(row);

        // Save after each row for crash recovery
        if filepath != "" {
            save_hdf5(results, filepath);
        }
    }

    if apply_calibration {
        results = radiance_calibration(results, grating);
    }

    results
}
```

### 2. step_scan_2d_TOP (experiments.py:758-800)
Fast grid scan using TOP for each X row:
```rhai
fn step_scan_2d_top(grating, grating_pos,
                    x_start, x_stop, x_step,
                    y_start, y_stop, y_step, y_velocity,
                    pulses_per_shot, filepath) {
    let results = [];

    for x in range(x_start, x_stop + x_step, x_step) {
        stage.set_velocity(5, y_velocity);

        // Use TOP for fast Y scan at this X position
        let (row, _) = top_acquisition(
            pulses_per_shot, x,
            y_start, y_stop, y_step
        );

        stage.set_velocity(5, 5);  // Reset to normal
        results.push(row);

        // Save intermediate
        save_hdf5(results, filepath);
    }

    results
}
```

### 3. multishot_step_2d (experiments.py:924-1001)
Grid scan collecting multiple spectra per position:
```rhai
fn multishot_step_2d(grating, grating_pos,
                     x_start, x_stop, x_step,
                     y_start, y_stop, y_step,
                     num_pulses, filepath) {
    // 4D data: [X, Y, Wavelength, Pulse]
    let results = [];

    for y in range(y_start, y_stop + y_step, y_step) {
        stage.y_move_abs(y);

        let row = [];
        for x in range(x_start, x_stop + x_step, x_step) {
            stage.x_move_abs(x);

            // Collect series of spectra at this point
            let series = custom_acquire_series(num_pulses);
            row.push(#{x: x, spectra: series});
        }
        results.push(#{y: y, row: row});

        save_hdf5(results, filepath);
    }

    results
}
```

